39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const COMPONENT_BLOCK_SIZE = 3;
57	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
58	
59	const basePremiumOf = (item: Item): number =>
60	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
61	
62	const groupByType = (items: Item[]): Item[][] => {
63	  const groups = new Map<string, Item[]>();
64	  for (const item of items) {
65	    const group = groups.get(item.type) ?? [];
66	    group.push(item);
67	    groups.set(item.type, group);
68	  }
69	  return [...groups.values()];
70	};
71	
72	const groupBasePremium = (group: Item[]): number => {
73	  if (group.length === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_BASE_PREMIUM;
74	  return group.reduce((sum, item) => sum + basePremiumOf(item), 0);
75	};
76	
77	const policyBasePremium = (items: Item[]): number =>
78	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
79	
80	const quotePremium = (items: Item[]): number => {
81	  const policyBase = policyBasePremium(items);
82	  const premiumBeforeFee =
83	    policyBase + percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
84	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
85	};
86	
87	const runStep = (step: Step): StepResult => {
88	  if (step.op === "quote") return { premium: quotePremium(step.items) };
89	  throw new Error("claim steps are not implemented yet");
90	};
91	
92	export const runScenario = (scenario: Scenario): ScenarioResult => ({
93	  results: scenario.steps.map(runStep),
94	});
